using Microsoft.Data.Sqlite;
namespace AyGest.Wpf.Services;
public sealed class BusinessService
{
 readonly Data.AppDb db; public BusinessService(Data.AppDb db)=>this.db=db; static string Now()=>DateTime.UtcNow.ToString("O");
 public long EnsureCompany(string name="Minha Empresa"){using var c=db.Open();using var q=c.CreateCommand();q.CommandText="SELECT id FROM companies LIMIT 1";var v=q.ExecuteScalar();if(v is not null)return Convert.ToInt64(v);q.CommandText="INSERT INTO companies(name,created_at) VALUES(@n,@d);SELECT last_insert_rowid();";q.Parameters.AddWithValue("@n",name);q.Parameters.AddWithValue("@d",Now());return Convert.ToInt64(q.ExecuteScalar());}
 public DataTableData Query(string sql,params (string,object)[] p){using var c=db.Open();using var q=c.CreateCommand();q.CommandText=sql;foreach(var a in p)q.Parameters.AddWithValue(a.Item1,a.Item2??DBNull.Value);using var r=q.ExecuteReader();var t=new DataTableData();for(int i=0;i<r.FieldCount;i++)t.Columns.Add(r.GetName(i));while(r.Read()){var row=new object[r.FieldCount];for(int i=0;i<r.FieldCount;i++)row[i]=r.IsDBNull(i)?null!:r.GetValue(i);t.Rows.Add(row);}return t;}
 public void Execute(string sql,params (string,object)[] p){using var c=db.Open();using var q=c.CreateCommand();q.CommandText=sql;foreach(var a in p)q.Parameters.AddWithValue(a.Item1,a.Item2??DBNull.Value);q.ExecuteNonQuery();}
 public long AddProduct(long company,string name,string sku,string barcode,decimal cost,decimal price,decimal vat,decimal min){using var c=db.Open();using var tx=c.BeginTransaction();using var q=c.CreateCommand();q.Transaction=tx;q.CommandText="INSERT INTO products(company_id,name,sku,barcode,cost,price,vat_rate,min_stock) VALUES(@c,@n,@s,@b,@co,@p,@v,@m);SELECT last_insert_rowid();";q.Parameters.AddWithValue("@c",company);q.Parameters.AddWithValue("@n",name);q.Parameters.AddWithValue("@s",sku??"");q.Parameters.AddWithValue("@b",barcode??"");q.Parameters.AddWithValue("@co",cost);q.Parameters.AddWithValue("@p",price);q.Parameters.AddWithValue("@v",vat);q.Parameters.AddWithValue("@m",min);var id=Convert.ToInt64(q.ExecuteScalar());q.CommandText="INSERT INTO stock(product_id,quantity) VALUES(@id,0)";q.Parameters.Clear();q.Parameters.AddWithValue("@id",id);q.ExecuteNonQuery();tx.Commit();return id;}
 public void AddCustomer(long company,string name,string nuit,string phone,string email)=>Execute("INSERT INTO customers(company_id,name,nuit,phone,email) VALUES(@c,@n,@u,@p,@e)",("@c",company),("@n",name),("@u",nuit),("@p",phone),("@e",email));
 public void AddSupplier(long company,string name,string nuit,string phone,string email)=>Execute("INSERT INTO suppliers(company_id,name,nuit,phone,email) VALUES(@c,@n,@u,@p,@e)",("@c",company),("@n",name),("@u",nuit),("@p",phone),("@e",email));
 string NextInvoice(long company,SqliteConnection c){using var q=c.CreateCommand();q.CommandText="SELECT COUNT(*)+1 FROM invoices WHERE company_id=@c";q.Parameters.AddWithValue("@c",company);return $"FT-{DateTime.Now:yyyy}-{Convert.ToInt64(q.ExecuteScalar()):D6}";}
 public long CreateInvoice(long company,long? customer,IEnumerable<(long product,string description,decimal qty,decimal price,decimal vat)> lines,string method){var ls=lines.ToList();if(ls.Count==0)throw new InvalidOperationException("A factura precisa de itens.");using var c=db.Open();using var tx=c.BeginTransaction();decimal sub=0,vat=0;foreach(var l in ls){if(l.qty<=0||l.price<0)throw new InvalidOperationException("Quantidade/preço inválido.");using var s=c.CreateCommand();s.Transaction=tx;s.CommandText="SELECT quantity FROM stock WHERE product_id=@p";s.Parameters.AddWithValue("@p",l.product);var available=Convert.ToDecimal(s.ExecuteScalar()??0);if(available<l.qty)throw new InvalidOperationException($"Stock insuficiente: {l.description}. Disponível: {available:0.##}");sub+=l.qty*l.price;vat+=l.qty*l.price*l.vat/100;}var number=NextInvoice(company,c);using var q=c.CreateCommand();q.Transaction=tx;q.CommandText="INSERT INTO invoices(company_id,customer_id,number,subtotal,vat,total,payment_method,created_at) VALUES(@c,@u,@n,@s,@v,@t,@m,@d);SELECT last_insert_rowid();";q.Parameters.AddWithValue("@c",company);q.Parameters.AddWithValue("@u",(object?)customer??DBNull.Value);q.Parameters.AddWithValue("@n",number);q.Parameters.AddWithValue("@s",sub);q.Parameters.AddWithValue("@v",vat);q.Parameters.AddWithValue("@t",sub+vat);q.Parameters.AddWithValue("@m",method);q.Parameters.AddWithValue("@d",Now());var id=Convert.ToInt64(q.ExecuteScalar());foreach(var l in ls){q.Parameters.Clear();q.CommandText="INSERT INTO invoice_items(invoice_id,product_id,description,quantity,unit_price,vat_rate,line_total) VALUES(@i,@p,@d,@q,@u,@v,@t)";q.Parameters.AddWithValue("@i",id);q.Parameters.AddWithValue("@p",l.product);q.Parameters.AddWithValue("@d",l.description);q.Parameters.AddWithValue("@q",l.qty);q.Parameters.AddWithValue("@u",l.price);q.Parameters.AddWithValue("@v",l.vat);q.Parameters.AddWithValue("@t",l.qty*l.price);q.ExecuteNonQuery();q.Parameters.Clear();q.CommandText="UPDATE stock SET quantity=quantity-@q WHERE product_id=@p";q.Parameters.AddWithValue("@q",l.qty);q.Parameters.AddWithValue("@p",l.product);q.ExecuteNonQuery();q.Parameters.Clear();q.CommandText="INSERT INTO stock_movements(product_id,type,quantity,reference,created_at) VALUES(@p,'SALE',@q,@r,@d)";q.Parameters.AddWithValue("@p",l.product);q.Parameters.AddWithValue("@q",-l.qty);q.Parameters.AddWithValue("@r",id);q.Parameters.AddWithValue("@d",Now());q.ExecuteNonQuery();}q.Parameters.Clear();q.CommandText="INSERT INTO cash_movements(session_id,type,description,amount,payment_method,created_at) SELECT id,'IN',@d,@a,@m,@x FROM cash_sessions WHERE company_id=@c AND status='open'";q.Parameters.AddWithValue("@d",$"Factura {number}");q.Parameters.AddWithValue("@a",sub+vat);q.Parameters.AddWithValue("@m",method);q.Parameters.AddWithValue("@x",Now());q.Parameters.AddWithValue("@c",company);q.ExecuteNonQuery();q.Parameters.Clear();q.CommandText="INSERT INTO audit_log(company_id,action,entity,entity_id,details,created_at) VALUES(@c,'CREATE','invoice',@i,@d,@x)";q.Parameters.AddWithValue("@c",company);q.Parameters.AddWithValue("@i",id);q.Parameters.AddWithValue("@d",$"Factura {number}; Total {sub+vat:N2}; Pagamento {method}");q.Parameters.AddWithValue("@x",Now());q.ExecuteNonQuery();tx.Commit();return id;}
 public void CancelInvoice(long id,string reason){if(string.IsNullOrWhiteSpace(reason))throw new InvalidOperationException("Motivo obrigatório.");using var c=db.Open();using var tx=c.BeginTransaction();using var q=c.CreateCommand();q.Transaction=tx;q.CommandText="SELECT company_id,status,total,number FROM invoices WHERE id=@i";q.Parameters.AddWithValue("@i",id);using var head=q.ExecuteReader();if(!head.Read())throw new InvalidOperationException("Factura não encontrada.");var company=Convert.ToInt64(head.GetValue(0));var status=head.GetString(1);var total=Convert.ToDecimal(head.GetValue(2));var number=head.GetString(3);head.Close();if(status!="issued")throw new InvalidOperationException("A factura não pode ser anulada.");q.Parameters.Clear();q.CommandText="SELECT product_id,quantity FROM invoice_items WHERE invoice_id=@i";q.Parameters.AddWithValue("@i",id);var items=new List<(long,decimal)>();using(var r=q.ExecuteReader())while(r.Read())items.Add((Convert.ToInt64(r.GetValue(0)),Convert.ToDecimal(r.GetValue(1))));foreach(var x in items){q.Parameters.Clear();q.CommandText="UPDATE stock SET quantity=quantity+@q WHERE product_id=@p";q.Parameters.AddWithValue("@q",x.Item2);q.Parameters.AddWithValue("@p",x.Item1);q.ExecuteNonQuery();q.Parameters.Clear();q.CommandText="INSERT INTO stock_movements(product_id,type,quantity,reference,created_at) VALUES(@p,'CANCEL',@q,@r,@d)";q.Parameters.AddWithValue("@p",x.Item1);q.Parameters.AddWithValue("@q",x.Item2);q.Parameters.AddWithValue("@r",id);q.Parameters.AddWithValue("@d",Now());q.ExecuteNonQuery();}q.Parameters.Clear();q.CommandText="UPDATE invoices SET status='cancelled',cancelled_at=@d,cancellation_reason=@r WHERE id=@i";q.Parameters.AddWithValue("@d",Now());q.Parameters.AddWithValue("@r",reason);q.Parameters.AddWithValue("@i",id);q.ExecuteNonQuery();q.Parameters.Clear();q.CommandText="INSERT INTO cash_movements(session_id,type,description,amount,payment_method,created_at) SELECT id,'OUT',@d,@a,'Reversão',@x FROM cash_sessions WHERE company_id=@c AND status='open'";q.Parameters.AddWithValue("@d",$"Anulação {number}");q.Parameters.AddWithValue("@a",total);q.Parameters.AddWithValue("@x",Now());q.Parameters.AddWithValue("@c",company);q.ExecuteNonQuery();q.Parameters.Clear();q.CommandText="INSERT INTO audit_log(company_id,action,entity,entity_id,details,created_at) VALUES(@c,'CANCEL','invoice',@i,@d,@x)";q.Parameters.AddWithValue("@c",company);q.Parameters.AddWithValue("@i",id);q.Parameters.AddWithValue("@d",reason);q.Parameters.AddWithValue("@x",Now());q.ExecuteNonQuery();tx.Commit();}
 public long OpenCash(long company,decimal opening){using var c=db.Open();using var q=c.CreateCommand();q.CommandText="SELECT id FROM cash_sessions WHERE company_id=@c AND status='open' LIMIT 1";q.Parameters.AddWithValue("@c",company);if(q.ExecuteScalar() is not null)throw new InvalidOperationException("Já existe um caixa aberto.");q.Parameters.Clear();q.CommandText="INSERT INTO cash_sessions(company_id,opened_at,opening_amount,expected_amount,status) VALUES(@c,@d,@o,@o,'open');SELECT last_insert_rowid();";q.Parameters.AddWithValue("@c",company);q.Parameters.AddWithValue("@d",Now());q.Parameters.AddWithValue("@o",opening);return Convert.ToInt64(q.ExecuteScalar());}
 public void CashMovement(long session,string type,string description,decimal amount,string method){if(amount<=0)throw new InvalidOperationException("Valor inválido.");Execute("INSERT INTO cash_movements(session_id,type,description,amount,payment_method,created_at) VALUES(@s,@t,@d,@a,@m,@x)",("@s",session),("@t",type),("@d",description),("@a",amount),("@m",method),("@x",Now()));}
 public void CloseCash(long session,decimal closing){using var c=db.Open();using var q=c.CreateCommand();q.CommandText="SELECT opening_amount,COALESCE((SELECT SUM(CASE WHEN type='IN' THEN amount ELSE -amount END) FROM cash_movements WHERE session_id=@s),0) FROM cash_sessions WHERE id=@s AND status='open'";q.Parameters.AddWithValue("@s",session);using var r=q.ExecuteReader();if(!r.Read())throw new InvalidOperationException("Caixa não encontrado.");var expected=Convert.ToDecimal(r.GetValue(0))+Convert.ToDecimal(r.GetValue(1));r.Close();q.Parameters.Clear();q.CommandText="UPDATE cash_sessions SET closed_at=@d,closing_amount=@a,expected_amount=@e,status='closed' WHERE id=@s";q.Parameters.AddWithValue("@d",Now());q.Parameters.AddWithValue("@a",closing);q.Parameters.AddWithValue("@e",expected);q.Parameters.AddWithValue("@s",session);q.ExecuteNonQuery();}
}
public sealed class DataTableData{public List<string> Columns{get;}=new();public List<object[]> Rows{get;}=new();}
